#include <stdio.h>
#include <stddef.h>

struct Student {
    int id;
    char name[16];
    double gpa;
    char grade;
};

int main(void) {
    printf("id   @ %zu\n", offsetof(struct Student, id));
    printf("name @ %zu\n", offsetof(struct Student, name));
    printf("gpa  @ %zu\n", offsetof(struct Student, gpa));
    printf("grade@ %zu\n", offsetof(struct Student, grade));
    printf("sizeof = %zu\n", sizeof(struct Student));
    return 0;
}
